package com.ias.gateway;
import com.ias.trust.Chain;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class FinanceGatewayBoundaryTest {
 @Test void executionStatusProjectionEdgesRemainExactAndCannotBorrowMoneyAuthority(){for(String edge:new String[]{"finance-ticket","stock-ticket"}){String path="/internal/ticket/fee-executions/projection";assertTrue(Chain.allowedEdge(edge,"POST",path));assertFalse(Chain.allowedEdge(edge,"GET",path));assertFalse(Chain.allowedEdge(edge,"POST",path+"/all"));}String stock="/internal/stock/finance-part-executions/projection";assertTrue(Chain.allowedEdge("finance-stock","POST",stock));assertFalse(Chain.allowedEdge("finance-stock","GET",stock));assertFalse(Chain.allowedEdge("notification-stock","POST",stock));assertFalse(Chain.allowedEdge("approval-ticket","POST","/internal/ticket/fee-executions/projection"));}
 @Test void quoteDiscoveryUsesExactReadOnlyRouteAndPrivateMembershipEdge(){String p="/api/ticket/tickets/"+U+"/finance-quote-references";assertTrue(GatewayApplication.allowed("GET",p));assertFalse(GatewayApplication.allowed("POST",p));assertFalse(GatewayApplication.allowed("GET",p+"/all"));assertTrue(Chain.allowedEdge("ticket-asset","POST","/internal/asset/finance-membership"));assertFalse(Chain.allowedEdge("ticket-asset","GET","/internal/asset/finance-membership"));assertFalse(Chain.allowedEdge("notification-asset","POST","/internal/asset/finance-membership"));}
 static final String U="00000000-0000-4000-8000-000000000001";
 @Test void frozenSourceRecoveryAndExplicitAbortHaveExactPublicRoutes(){String p="/api/finance/groups/"+U+"/quote-sources/"+U;assertTrue(GatewayApplication.allowed("GET",p));assertTrue(GatewayApplication.allowed("POST",p+"/abort"));assertFalse(GatewayApplication.allowed("POST",p));assertFalse(GatewayApplication.allowed("GET",p+"/abort"));assertFalse(GatewayApplication.allowed("DELETE",p));assertFalse(GatewayApplication.allowed("POST",p+"/release"));for(String action:new String[]{"reject","withdraw"})assertTrue(GatewayApplication.allowed("POST","/api/finance/groups/"+U+"/quotes/"+U+"/"+action));}
 @Test void exactSixFinanceRoutesAndNoAdminOrInternalProxy(){assertTrue(GatewayApplication.allowed("GET","/api/finance/tickets/"+U+"/group"));assertTrue(GatewayApplication.allowed("POST","/api/finance/tickets/"+U+"/group"));assertTrue(GatewayApplication.allowed("POST","/api/finance/groups/"+U+"/quotes"));assertTrue(GatewayApplication.allowed("GET","/api/finance/groups/"+U+"/quotes/"+U));assertTrue(GatewayApplication.allowed("POST","/api/finance/groups/"+U+"/quotes/"+U+"/confirm"));assertTrue(GatewayApplication.allowed("GET","/api/finance/groups/"+U+"/operations/"+U));assertFalse(GatewayApplication.allowed("POST","/api/finance/rules/publish"));assertFalse(GatewayApplication.allowed("GET","/internal/approval/fee-rule"));assertFalse(GatewayApplication.allowed("DELETE","/api/finance/groups/"+U+"/quotes/"+U));}
 @Test void financeEdgesArePositiveMethodAndPathLists(){assertTrue(Chain.allowedEdge("finance-ticket","POST","/internal/ticket/finance-context"));assertFalse(Chain.allowedEdge("finance-ticket","GET","/internal/ticket/finance-context"));assertFalse(Chain.allowedEdge("finance-ticket","POST","/internal/ticket/approval-references/settle"));assertTrue(Chain.allowedEdge("finance-asset","POST","/internal/asset/finance-membership"));assertTrue(Chain.allowedEdge("finance-approval","POST","/internal/approval/fee-rule"));assertFalse(Chain.allowedEdge("finance-approval","POST","/internal/approval/stock-context"));assertEquals("finance",Chain.peer("gateway-finance"));}
 @Test void laborExecutionRecoveryAndOwnerQueryAreExactPositiveLists(){String execute="/api/ticket/tickets/"+U+"/fee-executions";String recover="/api/ticket/tickets/"+U+"/fee-execution-operations/"+U;assertTrue(GatewayApplication.allowed("POST",execute));assertFalse(GatewayApplication.allowed("GET",execute));assertFalse(GatewayApplication.allowed("POST",execute+"/all"));assertTrue(GatewayApplication.allowed("GET",recover));assertFalse(GatewayApplication.allowed("POST",recover));assertFalse(GatewayApplication.allowed("GET",recover+"/all"));String query="/internal/ticket/fee-executions/query";assertTrue(Chain.allowedEdge("finance-ticket","POST",query));assertFalse(Chain.allowedEdge("finance-ticket","GET",query));assertFalse(Chain.allowedEdge("approval-ticket","POST",query));assertFalse(Chain.allowedEdge("finance-ticket","POST",query+"/all"));}
 @Test void feeExecutionProjectionUsesExactReadOnlyRoute(){String projection="/api/finance/groups/"+U+"/fee-execution-projection";assertTrue(GatewayApplication.allowed("GET",projection));assertFalse(GatewayApplication.allowed("POST",projection));assertFalse(GatewayApplication.allowed("GET",projection+"/all"));assertFalse(GatewayApplication.allowed("GET","/api/finance/groups/not-a-uuid/fee-execution-projection"));}
 @Test void stockOwnerEdgesCannotBorrowNotificationOrFinanceAuthority(){assertTrue(Chain.allowedEdge("stock-approval","POST","/internal/approval/stock-context"));assertTrue(Chain.allowedEdge("stock-ticket","POST","/internal/ticket/stock-executions/prepare"));assertFalse(Chain.allowedEdge("notification-ticket","POST","/internal/ticket/stock-executions/prepare"));assertTrue(Chain.allowedEdge("ticket-identity","POST","/internal/identity/stock-engineer-qualification"));assertFalse(Chain.allowedEdge("finance-identity","POST","/internal/identity/stock-engineer-qualification"));}
 @Test void financeVoucherContentUsesExactPutRoute(){String p="/api/ticket/tickets/"+U+"/finance-vouchers/"+U+"/content";assertTrue(GatewayApplication.allowed("PUT",p));assertFalse(GatewayApplication.allowed("POST",p));assertFalse(GatewayApplication.allowed("PUT",p+"/all"));assertFalse(GatewayApplication.allowed("PUT","/api/ticket/tickets/"+U+"/finance-vouchers"));}
}

